def is_acyclic(choices, features):
    visiting = set()
    visited = set()

    def visit(name):
        if name in visiting:
            return False
        if name in visited:
            return True
        visiting.add(name)
        row = choices[name]
        for dep in active_dependencies(row, features):
            if not visit(dep['name']):
                return False
        visiting.remove(name)
        visited.add(name)
        return True

    return all(visit(name) for name in choices)
